package companion

import (
	"bytes"
	"encoding/json"
	"strings"
)

// cyberPolicyDetector watches the response as it is forwarded. It retains at
// most one JSON response or SSE event, and only accepts a structured error
// code; text generated by a model cannot trigger an audit record.
type cyberPolicyDetector struct {
	stream    bool
	hit       bool
	code      string
	large     bool
	skipLine  bool
	skipEvent bool
	body      bytes.Buffer
	line      []byte
	event     []byte
}

const maxCyberPolicyEvent = 1 << 20
const maxCyberPolicyJSON = 64 << 10

func (d *cyberPolicyDetector) write(chunk []byte) {
	if d.hit || d.large && !d.stream {
		return
	}
	if !d.stream {
		if d.body.Len()+len(chunk) > maxCyberPolicyJSON {
			d.large = true
			d.body.Reset()
			return
		}
		_, _ = d.body.Write(chunk)
		return
	}
	for _, b := range chunk {
		if b != '\n' {
			if d.skipLine {
				continue
			}
			if len(d.line) >= maxCyberPolicyEvent {
				d.skipLine = true
				d.skipEvent = true
				d.line = nil
				continue
			}
			d.line = append(d.line, b)
			continue
		}
		if d.skipLine {
			d.skipLine = false
			d.line = nil
			continue
		}
		d.consumeLine()
		if d.hit {
			return
		}
	}
}

func (d *cyberPolicyDetector) consumeLine() {
	line := bytes.TrimSuffix(d.line, []byte{'\r'})
	d.line = nil
	if len(line) == 0 {
		d.finishEvent()
		return
	}
	if d.skipEvent {
		return
	}
	if !bytes.HasPrefix(line, []byte("data:")) {
		return
	}
	value := bytes.TrimSpace(line[len("data:"):])
	if len(d.event)+len(value)+1 > maxCyberPolicyEvent {
		d.event = nil
		d.skipEvent = true
		return
	}
	if len(d.event) > 0 {
		d.event = append(d.event, '\n')
	}
	d.event = append(d.event, value...)
}

func (d *cyberPolicyDetector) finishEvent() {
	if !d.skipEvent && len(d.event) > 0 {
		d.code = cyberPolicyErrorCode(d.event)
		d.hit = d.code != ""
	}
	d.event = nil
	d.skipEvent = false
}

func (d *cyberPolicyDetector) detected() bool {
	if d.stream {
		if len(d.line) > 0 {
			d.consumeLine()
		}
		d.finishEvent()
	} else if !d.large {
		d.code = cyberPolicyErrorCode(d.body.Bytes())
		d.hit = d.code != ""
	}
	return d.hit
}

func cyberPolicyErrorCode(raw []byte) string {
	var response struct {
		Type  string `json:"type"`
		Code  string `json:"code"`
		Error struct {
			Code string `json:"code"`
		} `json:"error"`
		Response struct {
			Error struct {
				Code string `json:"code"`
			} `json:"error"`
		} `json:"response"`
	}
	if json.Unmarshal(raw, &response) != nil {
		return ""
	}
	cyberCode := func(code string) string {
		if strings.EqualFold(code, "cyber_policy") {
			return "cyber_policy"
		}
		if strings.EqualFold(code, "cyber_abuse") {
			return "cyber_abuse"
		}
		return ""
	}
	if code := cyberCode(response.Error.Code); code != "" {
		return code
	}
	if code := cyberCode(response.Response.Error.Code); code != "" {
		return code
	}
	if response.Type == "error" {
		return cyberCode(response.Code)
	}
	return ""
}

func isCyberPolicyError(raw []byte) bool {
	return cyberPolicyErrorCode(raw) != ""
}
